INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64178823', 64178823, 'analyze_legacy', 'Kota Singkawang', 'kabkota', 'KELURAHAN KUALA', '7.01.01.2.06.0002 - Belanja Alat/Bahan untuk Kegiatan Kantor- Kertas dan Cover Sub Kegiatan Penyediaan Peralatan dan Perlengkapan Kantor Kelurahan Kuala Kecamatan Singkawang Barat Tahun 2026', 'Barang', 'E-Purchasing', 'Kalimantan Barat, Singkawang (Kota)', 4972800, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Kertas dan Cover', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Kertas dan Cover', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1402132);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64219303', 64219303, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa SOC', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Security Operations Center (SOC) adalah pusat kendali keamanan informasi yang berfungsi untuk memantau, mendeteksi, menganalisis, dan merespons ancaman siber secara terpusat dan real-time. SOC mengintegrasikan teknologi seperti SIEM, IDS/IPS, threat intelligence, serta pengumpulan log dari berbagai perangkat untuk memberikan visibilitas menyeluruh terhadap infrastruktur TI organisasi. Dengan keberadaan SOC, perusahaan dapat menjaga kerahasiaan, integritas, dan ketersediaan data sekaligus memastikan kelancaran operasional bisnis dari potensi serangan siber', 'Layanan Security Operations Center (SOC) berfungsi sebagai pusat pengawasan, deteksi, analisis, dan respons terhadap insiden keamanan siber yang terjadi pada infrastruktur teknologi informasi BMKG. SOC bertujuan untuk memastikan keamanan, ketersediaan, dan integritas sistem informasi serta data yang dikelola oleh BMKG melalui kegiatan pemantauan secara real-time dan analisis insiden keamanan. Fungsi utama dari kegiatan sewa SOC ini meliputi: 1. Melakukan pemantauan dan analisis keamanan terhadap seluruh log dan aktivitas jaringan serta sistem aplikasi yang dikumpulkan melalui log collector milik BMKG. 2. Menyediakan layanan SIEM (Security Information and Event Management) untuk korelasi dan analisis log secara otomatis guna mendeteksi potensi ancaman. 3. Menyediakan layanan CTI (Cyber Threat Intelligence) untuk pengumpulan dan analisis data intelijen global guna memberikan wawasan proaktif mengenai taktik, teknik, dan prosedur (TTP) penyerang sebelum serangan terjadi. 4. Melaksanakan response awal (incident response) terhadap temuan insiden keamanan informasi serta melakukan eskalasi sesuai tingkatan ancaman. 5. Menyediakan laporan keamanan secara periodik (mingguan dan bulanan) serta laporan insiden khusus bila terjadi anomali atau serangan siber. 6. Melaksanakan transfer pengetahuan (knowledge sharing) untuk peningkatan kapabilitas SDM internal BMKG dalam bidang keamanan informasi. Materi mencakup praktik terbaik keamanan siber, analisis tren ancaman, serta pelatihan penggunaan dashboard SOC.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1402133);
